# SPDX-License-Identifier: MIT
# Trusted mechanism controls for setup_script; each mode proves one kernel
# behaviour with direct system calls and exits 1 (failing setup, so the case
# is ERROR) when the behaviour is absent.
import errno, os, stat, sys
mode, args = sys.argv[1], sys.argv[2:]
NAME = errno.errorcode


def say(text):
    print(mode + ": " + text)


def die(text):
    say("CONTROL FAILED: " + text)
    sys.exit(1)


if mode == "rename-onto-dir":
    src = os.path.join(os.path.dirname(args[0]), ".rename-probe")
    open(src, "w").close()
    try:
        os.rename(src, args[0])
    except OSError as exc:
        if exc.errno != errno.EISDIR:
            die("rename gave %s" % NAME.get(exc.errno))
    else:
        die("rename succeeded")
    if not os.path.exists(src) or not os.path.isdir(args[0]):
        die("source or directory changed")
    os.unlink(src)
    say("rename(file, non-empty directory) -> EISDIR, both kept")
elif mode == "devfull":
    fd = os.open("/dev/full", os.O_WRONLY)
    try:
        os.write(fd, b"x")
    except OSError as exc:
        if exc.errno != errno.ENOSPC:
            die("write gave %s" % NAME.get(exc.errno))
    else:
        die("write succeeded")
    say("write(/dev/full) -> ENOSPC")
elif mode == "open":
    os.close(os.open(args[0], os.O_RDONLY))
    say("opened " + args[0])
elif mode == "procmem":
    fd = os.open("/proc/self/mem", os.O_RDONLY)
    if not stat.S_ISREG(os.fstat(fd).st_mode):
        die("/proc/self/mem is not a regular file")
    try:
        os.read(fd, 32768)
    except OSError as exc:
        if exc.errno != errno.EIO:
            die("read gave %s" % NAME.get(exc.errno))
    else:
        die("read at offset 0 succeeded")
    os.close(fd)
    say("open(/proc/self/mem) ok, S_ISREG, read at offset 0 -> EIO")
else:
    die("unknown mode")

